-- 039_memo_rewrite_update.sql
-- A section written by Update, told apart from one rewritten at a prompt.
--
-- Additive only. Two nullable columns and a check on memo_rewrite. No row is
-- changed and nothing is backfilled: every row already there is a prompted
-- rewrite, and NULL in both columns is what a prompted rewrite is.
--
-- source
--   NULL      a section rewritten at a person's prompt (012)
--   'update'  a section regenerated by Update - the memo's own documents and
--             the configuration in use, merged onto the saved text
--
-- config_revision
--   Update only. The revision the section was regenerated under. revise reads
--   it from the rows a person accepted and writes it on the new memo, so the
--   revision names the configuration its new text came from - not whatever
--   happens to be in use at the moment Save is pressed, which an
--   administrator may have changed in between. NULL on a prompted rewrite,
--   which changes no configuration.
--
-- The prompt column stays NOT NULL. An Update row carries a fixed sentence
-- there, written by composition.
--
-- What reads these: revise_memo (which revision to write, and whether to take
-- in documents filed since the memo's root), get_memo and list_rewrites (so
-- the screen says "updated" rather than "rewritten at a prompt").

ALTER TABLE memo_rewrite
  ADD COLUMN source VARCHAR(16) NULL
    COMMENT 'NULL = rewritten at a prompt. update = regenerated by Update.',
  ADD COLUMN config_revision INT NULL
    COMMENT 'Update only: the revision the section was regenerated under.',
  ADD CONSTRAINT chk_memo_rewrite_source
    CHECK (source IS NULL OR source = 'update');


-- Verification
--
